// variant of https://shadertoy.com/view/43yczR
// naive coloring here: https://www.shadertoy.com/view/l3GyRR

// --- random permutation in [0,15] from https://www.shadertoy.com/view/lXlSzf

  #define N 4          // emulate P=17 (prime) table then skip 1st
//#define N 16         // emulate P=257 (prime) table then skip 1st
#define P (N*N+1)      // must be prime  -> N = 1, 2, 4, 16, 256...
#define Nf float(N)
#define shuffle shuffle_FN   // FN, FP, FP2 :  choose the permutation func

int s; // seed
int shuffle0(ivec2 i)        // --- shuffle integers in N² + 1 range
{
    int C =  i.x + N*i.y;   
    int a=9, b=0;            // should be: a, b such that no v with v² = -b/a
    return  ( a*C*C*C + b*C + s ) % P; // permutation polynomial
}

int shuffle_FN(ivec2 i) {    // --- shuffle integers in N² + 1 range
    int v = shuffle0(i);
    return v != P-1 ? v : shuffle0(ivec2(0,N)); // we swap invpermut(N²),permut(N²)
}

// ---------------------


#define H(p)  fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453)
/*
float line(vec2 p, vec2 a,vec2 b) {                   // --- draw line
    p -= a, b -= a;
    return length(p - b * clamp(dot(p, b) / dot(b, b), 0., 1.));
}
*/
float arc(vec2 p, vec2 a,vec2 b) {                    // --- draw circle
    return abs( length( p - (a+b)/2. ) - length(a-b)/2. );  
}

float scurve(vec2 p, vec2 a,vec2 b) {                 // --- draw scurve
    p -= mix(a,b,smoothstep(a.yx,b.yx,p.yx));
    return abs( fract(a.x-b.x)==0. ? p.y : p.x );
} 

float sdEllipse( vec2 p, vec2 ab ) {                  // --- draw ellipse from iq https://www.shadertoy.com/view/4lsXDN
	p = abs(p);
    vec2 q = ab*(p-ab);
	float w = (q.x<q.y)? 1.57 : 0.;
    for( int i; i<5; i++ ){
        vec2 cs = vec2(cos(w),sin(w)),
              u = ab*vec2( cs.x,cs.y),
              v = ab*vec2(-cs.y,cs.x);
        w += dot(p-u,v) / ( dot(p-u,u)+dot(v,v) );
    }
    return sign( dot(p/ab,p/ab) - 1. )
          * length(p-ab*vec2(cos(w),sin(w)));
}
float ellipse(vec2 p, vec2 a,vec2 b) {                // --- draw ellipse
    vec2 c,r;
    fract(a.x)==0. ?  c = vec2(a.x,b.y), r = vec2(b.x,a.y)
                   :( c = vec2(b.x,a.y), r = vec2(a.x,b.y) );
    return abs( sdEllipse( p-c, abs(r-c) ) );
}

vec2 pos(int i, vec2 I) {                             // --- get a location on cell I edge for slot i
#if 0  // evenly spaced slots of edges
    return i<8 ? vec2( i/4 ,     (float(i%4)+.5)/4.) 
               : vec2( (float(i%4)+.5)/4. , i/4 -2 ) ;
#else  // random placed slots of edges
    return i<8 ? vec2( i/4 ,     H(I+vec2(i/4,0)+.7*float(i%4))) 
               : vec2( H(I+vec2(0,i/4-2)+.3*float(i%4)) , i/4 -2 ) ;
#endif
}


void mainImage( out vec4 O, vec2 u )
{
    vec2 R = iResolution.xy,
         U = 9.* u / R.y,                             // scaling
         I = floor(U);                                // cell id
         U -= I;                                      // cell local coords
    s = int(16.*H(I))+int(iTime);                     // seeding cell permutation
    float d = 9.;
    for( int i, j, k; k<16; k++ ) {                   // for each connection in truchet
        i = shuffle_FN(ivec2(k%4,k/4));               // pos 1
        k++;
        j = shuffle_FN(ivec2(k%4,k/4));               // pos 2
        vec2 A = pos(i,I), B = pos(j,I);
        d =  min( d,   i==j   ? length(U-A)-.01       // connected to itself
                   : i/4==j/4 ? arc (U, A, B )        // same edge: arc
                   : i/8==j/8 ? scurve(U, A, B )      // opposite edge: scurve
                   :            ellipse(U, A, B )     // adjacent edg: line
                );
    }
    O = vec4(smoothstep(12./R.y, 0., d));             // AA draw
    if (iMouse.z>0.) O.b += .5*mod(I.x+I.y,2.);       // checked to show grid
}
